diff --git a/src/frontier_solution/strategy.cc b/src/frontier_solution/strategy.cc
index b0790e8..fa825c9 100644
--- a/src/frontier_solution/strategy.cc
+++ b/src/frontier_solution/strategy.cc
@@ -1,28 +1,400 @@
-// Your search strategy goes here.
-//
-// This starter only restarts the program on fresh random inputs until the
-// budget is spent.  It compiles and runs, and it is a poor search: replace
-// the body of Run().  You may add files to this directory and include them
-// from here; see the task README for the rules on what this code may use.
-
 #include "strategy/strategy_api.h"

-namespace frontier {
+#include <algorithm>
+#include <cmath>
+#include <cstdint>
+#include <vector>

+namespace frontier {
 namespace {

-class RandomRestartSearch : public Strategy {
+uint32_t Mix(uint32_t x) {
+  x ^= x >> 16;
+  x *= 0x7feb352dU;
+  x ^= x >> 15;
+  x *= 0x846ca68bU;
+  return x ^ (x >> 16);
+}
+
+struct Counts {
+  int attempts = 0;
+  int failures = 0;
+  int hits = 0;
+  int gains = 0;
+  int useful = 0;
+};
+
+struct Action {
+  int k;
+  int target;
+  uint32_t context;
+  uint32_t prefix;
+  uint32_t compound;
+  uint32_t bidirectional;
+  uint32_t loop;
+  uint32_t site;
+  uint32_t sequence;
+  float bias;
+  float rank;
+};
+
+struct Seed {
+  const Execution* ex;
+  std::vector<Action> actions;
+  float promise;
+  float interest = 0;
+  std::vector<int> rare;
+  int used = 0;
+  int anchors[3] = {};
+};
+
+class CoverageSearch {
  public:
-  virtual void Run(Host& host) {
-    while (true) {
-      const Execution* ex = host.Restart();
-      host.Release(ex);
+  explicit CoverageSearch(Host& host)
+      : h(host), p(host.program()), n(p.num_branch_ids),
+        predecessors(n), distance(n), seen(n), visits(n), count(n), base(n),
+        resident(n), occurrence(n), last_iter(n), forward_hash(n), coupled(1 << 18), reversible(1 << 18), state_seen(1 << 17), state_visits(1 << 17), context(1 << 17), loop_stats(1 << 17), prefix(1 << 19), reached(1 << 19),
+        logarithm(65536) {
+    for (int b : p.branches) {
+      forward_hash[b] = Mix(b);
+      for (int t : p.successors[b]) predecessors[t].push_back(b);
+    }
+    for (int i = 0; i < 65536; ++i) logarithm[i] = std::log2(1.0 + i);
+  }
+
+  void Run() {
+    while (h.iterations_used() < h.budget()) {
+      const Execution* ex = nullptr;
+      int split = -1;
+      int arm = 0;
+      int old_cov = h.num_covered();
+      const Execution* parent = nullptr;
+      if (!pool.empty() && h.Uniform(9) != 0) {
+        for (int tries = 0; !ex && tries < 4; ++tries) {
+          int si = -1;
+          int ai = -1;
+          Choose(si, ai);
+          if (si < 0) break;
+          Seed& seed = pool[si];
+          Action a = seed.actions[ai];
+          seed.actions[ai] = seed.actions.back();
+          seed.actions.pop_back();
+          ++seed.used;
+          ++coupled[a.compound];
+          ++reversible[a.bidirectional];
+          ex = h.Negate(seed.ex, a.k);
+          bool hit = ex && ex->path.size() > seed.ex->constraint_pos[a.k] &&
+              ex->path[seed.ex->constraint_pos[a.k]] == a.target;
+          if (ex) { arm = a.target; parent = seed.ex; }
+          if (hit) split = a.k;
+          Update(count[a.target], ex != nullptr, hit);
+          Update(loop_stats[a.loop], ex != nullptr, hit);
+          Update(context[a.context], ex != nullptr, hit);
+          Update(prefix[a.prefix], ex != nullptr, hit);
+          RefreshBranch(a.target);
+        }
+      }
+      if (!ex) ex = h.Restart();
+      if (h.iterations_used() == h.budget()) { h.Release(ex); h.Restart(); return; }
+      int novelty = Add(ex, split, parent, arm);
+      if (arm && (old_cov < h.num_covered() || novelty >= 4)) {
+        ++count[arm].gains;
+        RefreshBranch(arm);
+      }
+    }
+  }
+
+ private:
+  Host& h;
+  const Program& p;
+  int n;
+  std::vector<std::vector<int> > predecessors;
+  std::vector<int> distance, seen, visits;
+  std::vector<Counts> count;
+  std::vector<float> base;
+  std::vector<int> resident, occurrence, last_iter;
+  std::vector<uint32_t> forward_hash;
+  std::vector<int> coupled, reversible, state_seen, state_visits;
+  std::vector<Counts> context, loop_stats, prefix;
+  std::vector<int> reached;
+  std::vector<float> logarithm;
+  std::vector<Seed> pool;
+  int coverage = -1;
+  int latest = -1;
+  size_t stored = 0;
+
+  float Log(int x) const { return logarithm[std::min(x, 65535)]; }
+
+  static void Update(Counts& c, bool feasible, bool hit) {
+    ++c.attempts;
+    if (!feasible) ++c.failures;
+    if (hit) ++c.hits;
+  }
+
+  void RefreshBranch(int b) {
+    const Counts& c = count[b];
+    float value = h.covered(b) ? 2.6f / (0.6f + distance[b]) : 6.5f;
+    value -= 0.40f * Log(visits[b]) + 0.66f * Log(c.attempts);
+    value -= 1.9f * (Log(c.attempts) - Log(c.attempts - c.failures));
+    value += 1.15f * (Log(2 + 3 * c.gains) - Log(2 + c.hits));
+    value += 1.35f * (Log(3 + c.useful) - Log(3 + c.attempts - c.failures));
+    base[b] = value;
+  }
+
+  void Distances() {
+    std::vector<int> queue;
+    queue.reserve(n);
+    for (int b : p.branches) {
+      distance[b] = 40;
+      if (!h.covered(b) && count[b].failures <= 5 + 3 * count[b].hits) {
+        distance[b] = 0;
+        queue.push_back(b);
+      }
+    }
+    for (size_t i = 0; i < queue.size(); ++i) {
+      int b = queue[i];
+      for (int t : predecessors[b]) {
+        if (distance[t] > distance[b] + 1) {
+          distance[t] = distance[b] + 1;
+          queue.push_back(t);
+        }
+      }
     }
+    for (int b : p.branches) RefreshBranch(b);
+    coverage = h.num_covered();
   }
+
+  float Score(const Action& a) const {
+    const Counts& local = context[a.context];
+    const Counts& exact = prefix[a.prefix];
+    const Counts& ls = loop_stats[a.loop];
+    float path_cost = 1.8f * Log(exact.attempts) + 0.5f * Log(reached[a.prefix])
+                    + 0.75f * Log(local.attempts);
+    float combination_cost = 1.65f * Log(coupled[a.compound]) + 1.8f * Log(reversible[a.bidirectional]) + 1.0f;
+    return a.bias + base[a.target] - std::min(path_cost, combination_cost)
+           - 2.0f * (Log(ls.attempts) - Log(ls.attempts - ls.failures))
+           - 0.52f * Log(state_visits[a.site]) - 0.32f * Log(state_visits[a.sequence])
+           - 1.65f * (Log(local.attempts) - Log(local.attempts - local.failures))
+           - 3.5f * (Log(exact.attempts) - Log(exact.attempts - exact.failures));
+  }
+
+  void Choose(int& best_seed, int& best_index) {
